import {settings} from './config.js';
import accueil from './scenes/01-accueil.js';
import serre from './scenes/02-serre.js';
import croisement from './scenes/03-croisement.js';
import conseiller from './scenes/04-conseiller.js';
import collections,{plants} from './scenes/05-collections.js';
import jardins from './scenes/06-jardins.js';
const scenes=[accueil,serre,croisement,conseiller,collections,jardins];
document.querySelector('#scenes').innerHTML=scenes.map(scene=>scene.render()).join('');
document.querySelector('.image-note').textContent='Visualisation IA · à remplacer par votre vraie serre';
if(!settings.reducedMotion){for(const id of ['accueil','serre']){const section=document.getElementById(id);const track=document.createElement('div');track.className='scene-track';section.before(track);track.append(section);section.classList.add('pinned-scene');}}
for(const scene of scenes){const section=document.getElementById(scene.id);if(section.classList.contains('photo-scene')){const media=document.createElement(scene.video?'video':'img');media.className='scene-bg';if(scene.video){media.src=scene.video;media.muted=true;media.playsInline=true;media.preload='metadata';media.setAttribute('aria-label',scene.label);media.addEventListener('loadedmetadata',()=>updateScroll());}else{media.src=scene.image;media.alt='';media.fetchPriority=scene.id==='accueil'?'high':'auto';media.loading=scene.id==='accueil'?'eager':'lazy';}section.prepend(media);}}
if(conseiller.video){document.querySelector('.advisor-media').innerHTML=`<video controls playsinline preload="metadata" aria-label="Présentation de votre conseiller"><source src="${conseiller.video}" type="video/mp4"><track kind="captions" srclang="fr" label="Français" src="assets/conseiller.vtt" default></video>`;}
const dialog=document.querySelector('#detail');
const content=document.querySelector('#detail-content');
function openDialog(html){content.innerHTML=html;if(!dialog.open)dialog.showModal();}
dialog.querySelector('.close').onclick=()=>dialog.close();
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
function contact(message='Bonjour GreenNouala, je souhaite discuter de mon projet de jardin.'){if(/^\d{8,15}$/.test(settings.whatsapp)){window.open(`https://wa.me/${settings.whatsapp}?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer');return;}openDialog(`<p class="eyebrow">VOTRE PROJET GREENNOUALA</p><h2>La conversation<br><em>commence ici.</em></h2><p>Le contact WhatsApp sera disponible dès que GreenNouala aura renseigné son numéro.</p><p id="contact-message"></p><button class="copy-button">Copier mon message</button><p class="dialog-note">Version de démonstration · aucun message n’est envoyé.</p>`);document.querySelector('#contact-message').textContent=message;document.querySelector('.copy-button').onclick=async event=>{try{await navigator.clipboard.writeText(message);event.target.textContent='Message copié ✓';}catch{event.target.textContent='Sélectionnez le message ci-dessus pour le copier.';}};}
document.addEventListener('click',event=>{const button=event.target.closest('.contact');if(button)contact(button.dataset.message);});
document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button);});document.querySelectorAll('.plant-card').forEach(card=>card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter);});
document.querySelectorAll('[data-plant]').forEach(button=>button.onclick=()=>{const plant=plants[button.dataset.plant];openDialog(`<img src="https://images.unsplash.com/${plant.image}?auto=format&fit=crop&w=900&q=85" alt="Photographie d’inspiration"><p class="eyebrow">${plant.tag}</p><h2>${plant.name}</h2><p>${plant.description}</p><p class="dialog-note">Photographie d’ambiance. Disponibilité et variété à confirmer auprès de GreenNouala.</p><button class="solid-button contact" data-message="Bonjour GreenNouala, je souhaite des renseignements sur : ${plant.name}.">Demander conseil <span>↗</span></button>`);});
const gardenContent={terrasse:['Imaginez des pots généreux, des feuillages qui créent de l’intimité et une terrasse où prendre le temps.','végétaliser ma terrasse'],cour:['Imaginez une cour plus fraîche, un coin d’ombre et des plantes adaptées à votre espace.','aménager ma cour'],jardin:['Imaginez des volumes, des allées et des plantations qui composent un jardin à votre rythme.','aménager mon jardin']};
document.querySelectorAll('[data-garden]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-garden]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button);});const [description,message]=gardenContent[button.dataset.garden];document.querySelector('#garden-description').textContent=description;document.querySelector('#garden-contact').dataset.message=`Bonjour GreenNouala, je souhaite ${message}.`;});
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}}),{threshold:.12});
document.querySelectorAll('.section-heading,.advisor-copy,.collection-top,.plant-card,.garden-copy').forEach(el=>{el.classList.add('reveal');observer.observe(el);});
let scheduled=false;
function updateScroll(){scheduled=false;const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('#progress').style.height=`${max>0?scrollY/max*100:0}%`;let active=0;scenes.forEach((scene,index)=>{const section=document.getElementById(scene.id);const rect=(section.closest('.scene-track')||section).getBoundingClientRect();if(rect.top<innerHeight*.55)active=index;const media=section.querySelector('.scene-bg');if(media&&!settings.reducedMotion&&rect.bottom>0&&rect.top<innerHeight){const progress=Math.max(0,Math.min(1,-rect.top/Math.max(1,rect.height-innerHeight)));if(media.tagName==='VIDEO'&&Number.isFinite(media.duration)){const time=progress*media.duration;if(Math.abs(media.currentTime-time)>.08)media.currentTime=time;}else media.style.transform=`translateY(${progress*45}px) scale(${1+progress*.12})`;}});document.querySelector('#scene-number').textContent=String(active+1).padStart(2,'0');}
addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(updateScroll);}},{passive:true});addEventListener('resize',updateScroll);updateScroll();
